mapper.select:
SELECT * FROM the_full_order.tb_account_purchase_order
 WHERE account_id = #{account_id}
AND purchase_order_id = #{purchase_order_id}
 ORDER BY ordered_at DESC

mapper.update:
UPDATE the_full_order.tb_account_purchase_order_item
   SET welstory_res_cd = #{welstory_res_cd}, welstory_error_msg = #{welstory_error_msg}
 WHERE purchase_order_id = #{purchase_order_id} AND client_ord_item = #{client_ord_item}

UPDATE the_full_order.tb_account_purchase_order_item
   SET received_qty = #{received_qty}
 WHERE purchase_order_id = #{purchase_order_id} AND client_ord_item = #{client_ord_item}
   AND received_qty = 0
